create extension if not exists "pgcrypto";
create type event_status as enum ('upcoming','active','completed','canceled','postponed');
create table events(id uuid primary key default gen_random_uuid(),slug text unique not null,event_date timestamptz not null,theme text,venue text not null,address text,status event_status not null default 'upcoming',jackpot_amount int not null default 1000,announcement text,prizes text,attendance int,recap text,recap_public boolean default false,image_url text,is_special boolean default false,replaces_event_id uuid references events,created_at timestamptz default now(),updated_at timestamptz default now());
create table rounds(id uuid primary key default gen_random_uuid(),event_id uuid not null references events on delete cascade,round_number smallint not null,theme text,bonus_value int not null,unique(event_id,round_number));
create table teams(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,logo_url text,archived_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table players(id uuid primary key default gen_random_uuid(),display_name text not null,created_at timestamptz default now());
create table team_memberships(id uuid primary key default gen_random_uuid(),team_id uuid references teams on delete cascade,player_id uuid references players on delete cascade,joined_at timestamptz default now(),left_at timestamptz,unique(team_id,player_id,joined_at));
create table event_registrations(id uuid primary key default gen_random_uuid(),event_id uuid references events on delete cascade,team_id uuid references teams,checked_in_at timestamptz,final_place int,unique(event_id,team_id));
create table round_scores(id uuid primary key default gen_random_uuid(),registration_id uuid references event_registrations on delete cascade,round_id uuid references rounds,standard_score int not null default 0,double_score_used boolean default false,created_at timestamptz default now(),unique(registration_id,round_id));
create table score_adjustments(id uuid primary key default gen_random_uuid(),registration_id uuid references event_registrations on delete cascade,points int not null,reason text not null,created_by uuid,created_at timestamptz default now());
create table bonuses(id uuid primary key default gen_random_uuid(),registration_id uuid references event_registrations on delete cascade,round_id uuid references rounds,correct boolean not null default false,points int not null default 0,unique(registration_id,round_id));
create table perks(id uuid primary key default gen_random_uuid(),registration_id uuid references event_registrations on delete cascade,round_id uuid references rounds,type text check(type in ('panty','bribe')),points int not null,metadata jsonb default '{}',created_at timestamptz default now());
create table event_results(id uuid primary key default gen_random_uuid(),registration_id uuid unique references event_registrations on delete cascade,total_points int not null,winner boolean default false,published boolean default false,published_at timestamptz,manual_total int,manual_reason text,created_at timestamptz default now(),updated_at timestamptz default now());
create table jackpot_records(id uuid primary key default gen_random_uuid(),event_id uuid unique references events on delete cascade,opening_amount int not null,closing_amount int not null,qualified_team_id uuid references teams,winner_team_id uuid references teams,rolled_over boolean default true,created_at timestamptz default now());
create table awards(id uuid primary key default gen_random_uuid(),event_id uuid references events on delete cascade,team_id uuid references teams,name text not null,description text,created_at timestamptz default now());
create table achievements(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text,icon text,criterion jsonb not null default '{}',active boolean default true,created_at timestamptz default now());
create table team_achievements(id uuid primary key default gen_random_uuid(),team_id uuid references teams on delete cascade,achievement_id uuid references achievements,earned_at timestamptz default now(),event_id uuid references events,unique(team_id,achievement_id,event_id));
create table announcements(id uuid primary key default gen_random_uuid(),title text not null,body text not null,published_at timestamptz,expires_at timestamptz,featured boolean default false,created_at timestamptz default now());
create table app_settings(key text primary key,value jsonb not null,updated_at timestamptz default now());
create table admin_users(id uuid primary key references auth.users on delete cascade,display_name text,role text not null default 'host',created_at timestamptz default now());
-- Phase 2-ready entities. Kept relational now so live play does not require a redesign.
create table game_sessions(id uuid primary key default gen_random_uuid(),event_id uuid references events,game_code text unique,status text default 'draft',started_at timestamptz,ended_at timestamptz);
create table questions(id uuid primary key default gen_random_uuid(),round_id uuid references rounds,prompt text not null,answer text not null,question_order int not null,points int not null,is_bonus boolean default false);
create table answer_submissions(id uuid primary key default gen_random_uuid(),session_id uuid references game_sessions,registration_id uuid references event_registrations,question_id uuid references questions,answer text,submitted_at timestamptz default now(),auto_correct boolean,host_correct boolean,points_awarded int,timer_ms_remaining int);
alter table events enable row level security;alter table teams enable row level security;alter table event_results enable row level security;
create policy "public completed events" on events for select using(status in ('upcoming','active','completed','canceled','postponed'));
create policy "public teams" on teams for select using(archived_at is null);
create policy "published results" on event_results for select using(published=true);
